      ('e0eb21f4-cca9-4db0-8f2a-43d073fff92c'::uuid,-7220045,'Nelie Lebrón Robles','Nelie','Lebrón Robles','Partido Independentista Puertorriqueño'),
      ('c7176754-56f3-458f-8ca7-23d64de9c874'::uuid,-7220046,'Denis Márquez','Denis','Márquez','Partido Independentista Puertorriqueño'),
      ('adabd9f7-53b5-4aad-a029-57c69e50e18f'::uuid,-7220047,'José Pérez Cordero','José','Pérez Cordero','Partido Nuevo Progresista'),
      ('bee5e141-9ae2-4455-ad7a-2c99561bb30d'::uuid,-7220048,'Tatiana Pérez Ramírez','Tatiana','Pérez Ramírez','Partido Nuevo Progresista'),
      ('e7d102d0-f8ab-43da-9615-b42b31fb0a04'::uuid,-7220049,'Lourdes Ramos','Lourdes','Ramos','Partido Nuevo Progresista'),
      ('89878f88-46c3-4e5c-a04e-4baef5b16242'::uuid,-7220050,'Gabriel Rodríguez Aguiló','Gabriel','Rodríguez Aguiló','Partido Nuevo Progresista'),
      ('f3f57652-abf2-4a9c-a677-fe1d1e765c80'::uuid,-7220051,'Ramón Torres','Ramón','Torres','Partido Popular Democrático'),
      ('4bb73fc7-13e0-4085-957f-673df733069b'::uuid,-7220052,'Pichy Torres Zamora','Pichy','Torres Zamora','Partido Nuevo Progresista'),
      ('eff0e804-96bb-4cdc-b9cb-9534c6b59a95'::uuid,-7220053,'Swanny Vargas Laureano','Swanny','Vargas Laureano','Partido Popular Democrático')
    ) AS v(id, ext, fullname, firstname, lastname, party)
   WHERE NOT EXISTS (SELECT 1 FROM essentials.politicians p WHERE p.external_id = v.ext);

  -- ---- seat everyone -----------------------------------------------------------------
  FOR r IN
    SELECT o.id AS office_id, p.id AS politician_id
      FROM (VALUES
        (-7200001,'STATE_EXEC','72',NULL),
        (-7210001,'STATE_UPPER','72001','Seat 1'),
        (-7210002,'STATE_UPPER','72001','Seat 2'),
        (-7210003,'STATE_UPPER','72002','Seat 1'),
        (-7210004,'STATE_UPPER','72002','Seat 2'),
        (-7210005,'STATE_UPPER','72003','Seat 1'),
        (-7210006,'STATE_UPPER','72003','Seat 2'),
        (-7210007,'STATE_UPPER','72004','Seat 1'),
        (-7210008,'STATE_UPPER','72004','Seat 2'),
        (-7210009,'STATE_UPPER','72005','Seat 1'),
        (-7210010,'STATE_UPPER','72005','Seat 2'),
        (-7210011,'STATE_UPPER','72006','Seat 1'),
        (-7210012,'STATE_UPPER','72006','Seat 2'),
        (-7210013,'STATE_UPPER','72007','Seat 1'),
        (-7210014,'STATE_UPPER','72007','Seat 2'),
        (-7210015,'STATE_UPPER','72008','Seat 1'),
        (-7210016,'STATE_UPPER','72008','Seat 2'),
        (-7210017,'STATE_UPPER','72000','Seat 1'),
        (-7210018,'STATE_UPPER','72000','Seat 2'),
        (-7210019,'STATE_UPPER','72000','Seat 3'),
        (-7210020,'STATE_UPPER','72000','Seat 4'),
        (-7210021,'STATE_UPPER','72000','Seat 5'),
        (-7210022,'STATE_UPPER','72000','Seat 6'),
        (-7210023,'STATE_UPPER','72000','Seat 7'),
        (-7210024,'STATE_UPPER','72000','Seat 8'),
        (-7210025,'STATE_UPPER','72000','Seat 9'),
        (-7210026,'STATE_UPPER','72000','Seat 10'),
        (-7210027,'STATE_UPPER','72000','Seat 11'),
        (-7210028,'STATE_UPPER','72000','Seat 12'),
        (-7220001,'STATE_LOWER','72001','Seat 1'),
        (-7220002,'STATE_LOWER','72002','Seat 1'),
        (-7220003,'STATE_LOWER','72003','Seat 1'),
        (-7220004,'STATE_LOWER','72004','Seat 1'),
        (-7220005,'STATE_LOWER','72005','Seat 1'),
        (-7220006,'STATE_LOWER','72006','Seat 1'),
        (-7220007,'STATE_LOWER','72007','Seat 1'),
        (-7220008,'STATE_LOWER','72008','Seat 1'),
        (-7220009,'STATE_LOWER','72009','Seat 1'),
        (-7220010,'STATE_LOWER','72010','Seat 1'),
        (-7220011,'STATE_LOWER','72011','Seat 1'),
        (-7220012,'STATE_LOWER','72012','Seat 1'),
        (-7220013,'STATE_LOWER','72013','Seat 1'),
        (-7220014,'STATE_LOWER','72014','Seat 1'),
        (-7220015,'STATE_LOWER','72015','Seat 1'),
        (-7220016,'STATE_LOWER','72016','Seat 1'),
        (-7220017,'STATE_LOWER','72017','Seat 1'),
        (-7220018,'STATE_LOWER','72018','Seat 1'),
        (-7220019,'STATE_LOWER','72019','Seat 1'),
        (-7220020,'STATE_LOWER','72020','Seat 1'),
        (-7220021,'STATE_LOWER','72021','Seat 1'),
        (-7220022,'STATE_LOWER','72022','Seat 1'),
        (-7220023,'STATE_LOWER','72023','Seat 1'),
        (-7220024,'STATE_LOWER','72024','Seat 1'),
        (-7220025,'STATE_LOWER','72025','Seat 1'),
        (-7220026,'STATE_LOWER','72026','Seat 1'),
        (-7220027,'STATE_LOWER','72027','Seat 1'),
        (-7220028,'STATE_LOWER','72028','Seat 1'),
        (-7220029,'STATE_LOWER','72029','Seat 1'),
        (-7220030,'STATE_LOWER','72030','Seat 1'),
        (-7220031,'STATE_LOWER','72031','Seat 1'),
        (-7220032,'STATE_LOWER','72032','Seat 1'),
        (-7220033,'STATE_LOWER','72033','Seat 1'),
        (-7220034,'STATE_LOWER','72034','Seat 1'),
        (-7220035,'STATE_LOWER','72035','Seat 1'),
        (-7220036,'STATE_LOWER','72036','Seat 1'),
        (-7220037,'STATE_LOWER','72037','Seat 1'),
        (-7220038,'STATE_LOWER','72038','Seat 1'),
        (-7220039,'STATE_LOWER','72039','Seat 1'),
        (-7220040,'STATE_LOWER','72040','Seat 1'),
        (-7220041,'STATE_LOWER','72000','Seat 1'),
        (-7220042,'STATE_LOWER','72000','Seat 2'),
        (-7220043,'STATE_LOWER','72000','Seat 3'),
        (-7220044,'STATE_LOWER','72000','Seat 4'),
        (-7220045,'STATE_LOWER','72000','Seat 5'),
        (-7220046,'STATE_LOWER','72000','Seat 6'),
        (-7220047,'STATE_LOWER','72000','Seat 7'),
        (-7220048,'STATE_LOWER','72000','Seat 8'),
        (-7220049,'STATE_LOWER','72000','Seat 9'),
        (-7220050,'STATE_LOWER','72000','Seat 10'),
        (-7220051,'STATE_LOWER','72000','Seat 11'),
        (-7220052,'STATE_LOWER','72000','Seat 12'),
        (-7220053,'STATE_LOWER','72000','Seat 13')
      ) AS m(ext, dt, geo, descr)
      JOIN essentials.politicians p ON p.external_id = m.ext
      JOIN essentials.districts d
        ON d.geo_id = m.geo AND d.district_type = m.dt AND lower(d.state) = 'pr'
      JOIN essentials.offices o
        ON o.district_id = d.id AND o.description IS NOT DISTINCT FROM m.descr
  LOOP
    PERFORM essentials.seat_officeholder(
      r.office_id, r.politician_id, DATE '2025-01-02', c_src, 'elected', 'day');
  END LOOP;

  -- ---- post-verify -------------------------------------------------------------------
  SELECT count(*) INTO v_n FROM essentials.districts WHERE lower(state) = 'pr'
     AND district_type IN ('STATE_UPPER','STATE_LOWER','STATE_EXEC');
  IF v_n <> 51 THEN
    RAISE EXCEPTION 'expected 51 PR districts, found %', v_n;
  END IF;

  SELECT count(*) INTO v_n
    FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
    JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE lower(d.state) = 'pr' AND d.district_type = 'STATE_UPPER'
     AND och.politician_id IS NOT NULL;
  IF v_n <> 28 THEN RAISE EXCEPTION 'expected 28 PR senators, found %', v_n; END IF;

  SELECT count(*) INTO v_n
    FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
    JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE lower(d.state) = 'pr' AND d.district_type = 'STATE_LOWER'
     AND och.politician_id IS NOT NULL;
  IF v_n <> 53 THEN RAISE EXCEPTION 'expected 53 PR representatives, found %', v_n; END IF;

  IF NOT EXISTS (SELECT 1 FROM essentials.offices o
                   JOIN essentials.districts d ON d.id = o.district_id
                   JOIN essentials.office_current_holder och ON och.office_id = o.id
                   JOIN essentials.politicians p ON p.id = och.politician_id
                  WHERE lower(d.state) = 'pr' AND d.district_type = 'STATE_EXEC'
                    AND o.title = 'Governor' AND p.external_id = -7200001) THEN
    RAISE EXCEPTION 'the Governor of Puerto Rico is not seated';
  END IF;

  -- Every seat filled: no office left holderless, which would render as a phantom vacancy.
  SELECT count(*) INTO v_n
    FROM essentials.offices o JOIN essentials.districts d ON d.id = o.district_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE lower(d.state) = 'pr' AND d.district_type IN ('STATE_UPPER','STATE_LOWER','STATE_EXEC')
     AND och.politician_id IS NULL;
  IF v_n <> 0 THEN RAISE EXCEPTION '% PR seats have no holder', v_n; END IF;

  -- Parties preserved verbatim: nothing was translated into the U.S. two-party split.
  IF EXISTS (SELECT 1 FROM essentials.politicians
              WHERE external_id BETWEEN -7299999 AND -7200000
                AND party IN ('Democrat','Democratic','Republican')) THEN
    RAISE EXCEPTION 'a Puerto Rico party was mapped onto a U.S. party';
  END IF;

  -- Every district-based seat has usable geometry, so residents can actually reach it.
  SELECT count(*) INTO v_n
    FROM essentials.districts d
   WHERE lower(d.state) = 'pr' AND d.district_type IN ('STATE_UPPER','STATE_LOWER')
     AND NOT EXISTS (SELECT 1 FROM essentials.geofence_boundaries gp
                      WHERE gp.geo_id = d.geo_id AND gp.mtfcc = d.mtfcc
                        AND public.ST_IsValid(gp.geometry) AND NOT public.ST_IsEmpty(gp.geometry));
  IF v_n <> 0 THEN RAISE EXCEPTION '% PR legislative districts lack valid geometry', v_n; END IF;

  RAISE NOTICE 'Puerto Rico: governor + 28 senators + 53 representatives seated';
END $$;
